if(!types.includes('Manga')){types.push('Manga');labels.push('Manga');}
owned=function(x){return items.find(y=>FolioIdentity.same(y,x));};
const discovery=document.createElement('section');discovery.id='discovery';
discovery.innerHTML=`<div class="discover-heading"><small>YOUR NEXT GREAT FIND</small><h1>Find your next<span>.</span></h1><p>Movies, games, music, and worlds worth getting lost in.</p></div><form id="live-form" class="discover-search"><label for="live-query" class="sr-only">Search titles</label><input id="live-query" type="search" required maxlength="200" placeholder="Search any title — try Portal 2" autocomplete="off"><span class="search-live-indicator" aria-hidden="true">⌕</span></form><div class="discover-filters"><label>Media<select id="live-kind"><option value="">All media</option>${Object.entries(mediaTypes).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Source<select id="live-provider"><option value="">All providers</option>${['tmdb','igdb','vndb','mangaupdates','musicbrainz','apple','anilist'].map(p=>`<option>${p}</option>`).join('')}</select></label><label>Release year<input id="live-year" type="number" min="1800" max="2200" placeholder="Any year"></label><label>Genre<select id="live-genre"><option value="">All genres</option></select></label><label>Platform<select id="live-platform"><option value="">All platforms</option></select></label><label>Library<select id="live-owned"><option value="">All titles</option><option value="new">Not in library</option><option value="owned">In library</option></select></label><label>Sort<select id="live-sort"><option value="relevance">Best match</option><option value="popular">Most rated</option><option value="newest">Newest</option><option value="title">Title A–Z</option></select></label><button id="live-reset" type="button" class="secondary">Reset filters</button></div><div class="discover-summary"><p id="live-status" role="status">Search a title to discover live results from connected providers.</p><span id="live-count"></span></div><details class="discover-note"><summary>Provider availability</summary><p id="live-providers"></p></details><p class="discover-note">Year, genre, platform and library filters apply to loaded results. Load more to broaden them.</p><div id="live-results" class="discover-grid"></div><button id="live-more" class="secondary" hidden>Load more results</button><p class="discover-note">Metadata and ratings belong to their credited sources. TMDB: This product uses the TMDB API but is not endorsed or certified by TMDB.</p>`;
