const liveEl=id=>document.getElementById(id);
const baseRender=render;render=function(){baseRender();const searching=view==='catalog';discovery.hidden=!searching;if(searching)liveEl('library-page').hidden=true;paintLibrarySources();};render();
async function metadataGet(path,signal){const r=await fetch('/api/metadata/'+path,{signal});const body=await r.json();if(!r.ok)throw Error(typeof body.detail==='string'?body.detail:'This provider is unavailable. Please try again.');return body;}
function imageFor(m){return (m.image_sexual>0||m.image_violence>1)?'':safeMediaUrl(m.image_url||'');}
function plainDescription(m){const s=m.description||'';if(m.description_format==='html'){const doc=new DOMParser().parseFromString(s,'text/html');return doc.body.textContent||'';}return s.replace(/\[\/?(?:url|b|i|u|spoiler)(?:=[^\]]*)?\]/gi,'');}
function fromMetadata(m){return {id:m.id,title:m.title,type:m.kind==='album'||m.kind==='track'?'Music':mediaTypes[m.kind],year:m.release_date?.slice(0,4)||'',creator:(m.creators||[]).join(', '),genre:m.genres.join(', '),description:plainDescription(m),coverUrl:imageFor(m),symbol:'✦',color:colors[0],sources:allRatings(m).map(r=>[r.label,r.value]),metadata:m,added:Date.now()};}
function appleBadge(m){const apple=FolioIdentity.records(m).find(r=>r.source.provider==='apple');return apple?`<a class="apple-badge" href="${esc(safeMediaUrl(apple.source.url)||'#')}" target="_blank" rel="noopener noreferrer" aria-label="Listen on Apple Music"><img src="https://tools.applemediaservices.com/api/badges/listen-on-apple-music/badge/en-us?size=250x83" alt="Listen on Apple Music"></a>`:'';}
function allRatings(m){return (m.ratings||[]).concat(...(m.enrichments||[]).map(e=>e.ratings||[]));}
function displayScore(value){return FolioSearch.score(value);}
function ratingsMarkup(m){return allRatings(m).map(r=>`<span class="live-rating"><b>${esc(displayScore(r.value))}</b> ${esc(r.label)}</span>`).join('');}
function facets(){for(const [id,field,label] of [['live-genre','genres','All genres'],['live-platform','platforms','All platforms']]){const el=liveEl(id),prior=el.value;el.innerHTML=`<option value="">${label}</option>`+[...new Set(liveRecords.flatMap(m=>m[field]||[]))].sort().map(v=>`<option>${esc(v)}</option>`).join('');el.value=[...el.options].some(o=>o.value===prior)?prior:'';}}
function drawResults(){let shown=FolioIdentity.editions(FolioSearch.rank(FolioIdentity.group(liveRecords),liveQuery)).filter(m=>(!liveEl('live-year').value||m.release_date?.startsWith(liveEl('live-year').value))&&(!liveEl('live-genre').value||m.genres.includes(liveEl('live-genre').value))&&(!liveEl('live-platform').value||m.platforms.includes(liveEl('live-platform').value))&&(!liveEl('live-owned').value||(liveEl('live-owned').value==='owned')===!!owned(fromMetadata(m))));const sort=liveEl('live-sort').value;if(sort==='popular')shown.sort((a,b)=>(b.rating_count||0)-(a.rating_count||0));if(sort==='title')shown.sort((a,b)=>a.title.localeCompare(b.title));if(sort==='newest')shown.sort((a,b)=>(b.release_date||'').localeCompare(a.release_date||''));liveEl('live-count').textContent=liveRecords.length?`${shown.length} titles · ${liveRecords.length} source records`:'';
liveDisplayed=shown;liveEl('live-results').innerHTML=shown.map(m=>{const img=imageFor(m),entry=owned(fromMetadata(m));return `<article class="discover-card"><button class="discover-preview" data-preview="${esc(m.id)}" aria-label="Details for ${esc(m.title)}"><div class="discover-art"><span class="art-fallback" aria-hidden="true">${esc(m.title.slice(0,1))}</span>${img?`<img src="${esc(img)}" loading="lazy" referrerpolicy="no-referrer" alt="">`:''}<span class="discover-kind">${esc(mediaTypes[m.kind])}</span></div><div class="discover-card-body"><small>${esc(sourceNames(m))} · ${esc(m.release_date?.slice(0,4)||'Year unknown')}</small><h2>${esc(m.title)}</h2>${m.version_options?.length?`<span class="edition-label">${m.version_options.length+1} editions / sources</span>`:''}<p>${esc((m.creators||[]).join(', ')||m.genres.slice(0,2).join(' · ')||mediaTypes[m.kind])}</p><div class="live-ratings">${ratingsMarkup(m)||'<span class="unrated">View details</span>'}</div></div></button>${appleBadge(m)}<button class="discover-add ${entry?'is-owned':''}" data-import="${esc(m.id)}" ${entry?'disabled':''}>${entry?'✓ In library':'＋ Add to library'}</button></article>`;}).join('')||`<div class="discover-empty"><h2>${liveLoading?'Searching your next favorite…':liveQuery?'No titles match these filters.':'A whole world, one search.'}</h2><p>${liveLoading?'Fetching live metadata from providers.':liveQuery?'Try resetting filters or loading more results.':'Search for a favorite or something you have been meaning to try.'}</p></div>`;
liveEl('live-more').hidden=!liveMore;liveEl('live-more').disabled=liveLoading;discovery.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>showLive(liveDisplayed.find(m=>m.id===b.dataset.preview)));discovery.querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>importLive(liveDisplayed.find(m=>m.id===b.dataset.import),b));discovery.querySelectorAll('img').forEach(img=>img.onerror=()=>{img.hidden=true;});}
async function loadResults(append=false){clearTimeout(liveTimer);searchController?.abort();searchController=new AbortController();const seq=++liveSeq;liveLoading=true;const page=append?livePage+1:1;if(!append){liveQuery=liveEl('live-query').value.trim();liveRequest={q:liveQuery};for(const [id,param] of [['live-kind','kind'],['live-provider','provider']])if(liveEl(id).value)liveRequest[param]=liveEl(id).value;liveRecords=[];liveMore=false;drawResults();}liveEl('live-status').textContent='Searching providers…';liveEl('live-more').disabled=true;liveEl('live-results').setAttribute('aria-busy','true');try{const queries=append?[liveRequest.q]:FolioSearch.variants(liveRequest.q);
const responses=await Promise.allSettled(queries.map(q=>metadataGet('search?'+new URLSearchParams({...liveRequest,q,page}),searchController.signal)));
const successes=responses.filter(r=>r.status==='fulfilled').map(r=>r.value);if(!successes.length)throw responses[0].reason;
const data={...successes[0],results:successes.flatMap(r=>r.results),providers:[...new Map(successes.flatMap(r=>r.providers).map(s=>[s.provider+':'+s.kind,s])).values()],more:successes[0].more};if(seq!==liveSeq)return;livePage=page;liveMore=data.more;liveRecords=[...new Map([...liveRecords,...data.results].map(m=>[m.id,m])).values()];facets();liveEl('live-status').textContent=`Results for “${liveQuery}”`;liveEl('live-providers').textContent=data.providers.map(p=>`${p.provider}${p.kind?' ('+mediaTypes[p.kind]+')':''}: ${p.status.replaceAll('_',' ')}`).join(' · ');}catch(e){if(seq===liveSeq&&e.name!=='AbortError')liveEl('live-status').textContent=e.message;}finally{if(seq===liveSeq){liveLoading=false;liveEl('live-results').setAttribute('aria-busy','false');drawResults();}}}
function sourceNames(m){return [...new Set(FolioIdentity.records(m).map(r=>r.source.provider))].map(n=>({musicbrainz:'MusicBrainz',apple:'Apple Music',tmdb:'TMDB',igdb:'IGDB',vndb:'VNDB',mangaupdates:'MangaUpdates',anilist:'AniList'}[n]||n)).join(' + ');}
async function getDetail(m){const rows=FolioIdentity.records(m);const fetched=await Promise.allSettled(rows.map(r=>metadataGet('items/'+[r.source.provider,r.kind,r.source.id].map(encodeURIComponent).join('/')+'?enrich=true')));if(fetched.every(r=>r.status==='rejected'))throw fetched[0].reason;const fresh=rows.map((r,i)=>fetched[i].status==='fulfilled'?{...r,...fetched[i].value,external_ids:{...r.external_ids,...fetched[i].value.external_ids},search_priority:fetched[i].value.search_priority??r.search_priority}:r);const mb=fresh.find(r=>r.source.provider==='musicbrainz'&&r.kind==='album'&&r.external_ids?.apple);if(mb&&!fresh.some(r=>r.source.provider==='apple'&&r.source.id===mb.external_ids.apple)){try{const linked=await metadataGet('items/apple/album/'+encodeURIComponent(mb.external_ids.apple));fresh.push(linked);}catch{ /* Keep the primary metadata usable if its linked catalog is unavailable. */ }}const combined=FolioIdentity.combine(fresh);if(!combined)throw Error('These sources no longer agree. Search again to review them separately.');return m.version_options?{...combined,version_options:m.version_options}:combined;}
const liveAddDialog=document.createElement('dialog');liveAddDialog.id='live-add-dialog';document.body.append(liveAddDialog);
let addSeq=0;
async function importLive(m,button){
  const seq=++addSeq;
  liveAddDialog.innerHTML='<button class="close" aria-label="Cancel adding title">×</button><p role="status">Loading title…</p>';
  liveAddDialog.querySelector('.close').onclick=()=>liveAddDialog.close();
  if(!liveAddDialog.open)liveAddDialog.showModal();
  try{
    const detail=await getDetail(m);if(seq!==addSeq||!liveAddDialog.open)return;
    const entry=fromMetadata(detail);
    if(owned(entry)){liveAddDialog.close();toast('Already in your library');drawResults();return;}
    liveAddDialog.innerHTML=`<button class="close" aria-label="Cancel adding title">×</button><small>MAKE IT YOURS</small><h2>Add ${esc(entry.title)}</h2><p class="discover-note">${esc(sourceNames(detail))}${detail.facts?.Edition?' · '+esc(detail.facts.Edition):''}</p><p class="muted">Add straight to your library, choose collections, or edit before saving.</p><form id="live-add-form"><fieldset><legend>Collections (optional)</legend>${collections.map(c=>`<label class="collection-member"><input type="checkbox" name="collection" value="${esc(c.id)}">${esc(c.name)}</label>`).join('')||'<p class="muted">Create collections in Library → Collections.</p>'}</fieldset><label class="favorite-choice"><input type="checkbox" name="favorite"><span class="favorite-icon" aria-hidden="true">♥</span> Add as a favorite</label><button type="button" class="secondary" id="live-customize">Edit before adding</button><div id="live-add-fields" hidden><label>Title<input name="title" required maxlength="200" value="${esc(entry.title)}"></label><label>Status<select name="status">${statuses.map(s=>`<option value="${esc(s)}">${esc(s==='Want to experience'?'Up next':s)}</option>`).join('')}</select></label><label>Your rating<select name="rating"><option value="0">Not rated</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}">${i+1} / 10</option>`).join('')}</select></label><label>Genre<input name="genre" value="${esc(entry.genre)}"></label><label>Notes<textarea name="notes" maxlength="3000"></textarea></label></div><p id="live-add-error" role="alert"></p><div class="actions"><button type="button" class="secondary" id="live-add-cancel">Cancel</button><button type="submit" class="primary">Add to library</button></div></form>`;
    const form=liveAddDialog.querySelector('form');form.elements.status.value='Want to experience';
    liveAddDialog.querySelector('.close').onclick=liveAddDialog.querySelector('#live-add-cancel').onclick=()=>liveAddDialog.close();
    liveAddDialog.querySelector('#live-customize').onclick=e=>{liveAddDialog.querySelector('#live-add-fields').hidden=false;e.currentTarget.hidden=true;form.elements.title.focus();};
    form.onsubmit=e=>{
      e.preventDefault();if(owned(entry)){toast('Already in your library');liveAddDialog.close();drawResults();return;}
      const candidate=items.find(y=>FolioIdentity.possible(y,entry));if(candidate&&!confirm(`A similar title is already in your library: ${candidate.title}. Provider IDs do not confirm a match. Add separately?`))return;
      const title=form.elements.title.value.trim();if(!title){form.elements.title.focus();return;}
      Object.assign(entry,{title,status:form.elements.status.value,rating:Number(form.elements.rating.value),genre:form.elements.genre.value.trim(),notes:form.elements.notes.value,favorite:form.elements.favorite.checked});
      const selected=new Set([...form.querySelectorAll('[name="collection"]:checked')].map(el=>el.value));
      const before=collections.map(c=>({...c,members:[...c.members]}));items.unshift(entry);
      if(!persist()){items.shift();return;}
      collections.forEach(c=>{if(selected.has(c.id))c.members=[...new Set([...c.members,entry.id])];});
      if(selected.size&&!saveCollections()){items.shift();collections=before;persist();liveAddDialog.querySelector('#live-add-error').textContent='Could not save collections. Please try again.';return;}
      liveAddDialog.close();if(liveDialog.open)liveDialog.close();toast('Added to your library');render();drawResults();
    };
  }catch(e){if(seq===addSeq&&liveAddDialog.open)liveAddDialog.querySelector('p').textContent=e.message;}
}
function detailMarkup(m){
 const img=imageFor(m),all=allRatings(m),reviews=(m.enrichments||[]).filter(e=>e.reviews);
 const facts={'Media':mediaTypes[m.kind],'Release date':m.release_date||'Unknown',...(m.facts||{})};
 if(m.original_title&&m.original_title!==m.title)facts['Original title']=m.original_title;
 if(m.rating_count)facts['Source rating votes']=Number(m.rating_count).toLocaleString();
 const missing=(m.enrichment_status||[]).filter(s=>s.status!=='ok');
 const links=[...FolioIdentity.records(m).map(r=>r.source),...(m.enrichments||[]).map(e=>e.source)];
 if(m.external_ids.imdb)links.push({provider:'IMDb',url:'https://www.imdb.com/title/'+encodeURIComponent(m.external_ids.imdb)+'/'});
 if(m.external_ids.steam)links.push({provider:'Steam store',url:'https://store.steampowered.com/app/'+encodeURIComponent(m.external_ids.steam)+'/'});
 return `<button class="close" aria-label="Close provider details">×</button><div class="live-detail-top">${img?`<img src="${esc(img)}" referrerpolicy="no-referrer" alt="${esc(m.title)} cover">`:''}<div><small>${esc(mediaTypes[m.kind])} · ${esc(m.release_date?.slice(0,4)||'Date unknown')}</small><h2>${esc(m.title)}</h2>${m.version_options?.length?`<span class="edition-label">${m.version_options.length+1} editions / sources</span>`:''}<p>${esc((m.creators||[]).join(', '))}</p><p class="discover-note">${esc(sourceNames(m))} · Live metadata</p></div></div>${appleBadge(m)}<section class="live-detail-section"><h3>Ratings & reviews</h3><div class="source-score-grid">${all.map(r=>`<a class="source-score" href="${esc(safeMediaUrl(r.source.url)||'#')}" target="_blank" rel="noopener noreferrer"><span>${esc(r.label)}</span><strong>${esc(displayScore(r.value))}</strong><small>${esc(r.source.provider)} ↗</small></a>`).join('')}${reviews.map(e=>`<a class="source-score" href="${esc(safeMediaUrl(e.source.url)||'#')}" target="_blank" rel="noopener noreferrer"><span>Steam reviews</span><strong>${e.reviews.positive_percent==null?'Unrated':esc(displayScore(e.reviews.positive_percent))+'%'}</strong><small>${esc(e.reviews.label||'Positive reviews')} · ${Number(e.reviews.total).toLocaleString()} reviews</small></a>`).join('')}</div>${!all.length&&!reviews.length?'<p class="muted">This source has not supplied an audience rating.</p>':''}${missing.map(s=>`<p class="rating-availability">${s.provider==='omdb'?'IMDb / Rotten Tomatoes / Metacritic (via OMDb)':esc(s.provider)}: ${s.status==='not_configured'?'API key not configured':s.status==='not_found'?'No rating found for this linked record':'Temporarily unavailable'}.</p>`).join('')}<p class="discover-note">Each score retains its source and original scale. Personal ratings are kept separately.</p></section>${editionOptionsMarkup(m)}<section class="live-detail-section"><h3>About this title</h3><dl class="live-facts">${Object.entries(facts).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${m.genres.length?`<div class="live-tags">${m.genres.map(g=>`<span>${esc(g)}</span>`).join('')}</div>`:''}${m.platforms.length?`<h4>Platforms</h4><div class="live-tags">${m.platforms.map(g=>`<span>${esc(g)}</span>`).join('')}</div>`:''}</section><section class="live-detail-section"><h3>Overview</h3><p class="live-description">${esc(plainDescription(m)||'No description supplied by this source.')}</p></section><section class="live-detail-section"><h3>Sources & links</h3><div class="live-source-links">${[...new Map(links.map(l=>[l.url,l])).values()].map(l=>`<a href="${esc(safeMediaUrl(l.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(l.provider)} ↗</a>`).join('')}</div><p class="discover-note">Metadata fetched ${esc(new Date(m.source.fetched_at).toLocaleString())}. Ratings may describe different audiences and are never averaged.</p></section><div class="live-detail-actions">${liveActionsMarkup(m)}</div>`;
}
function editionOptionsMarkup(m){return m.version_options?.length?`<section class="live-detail-section"><h3>Other editions & sources</h3><p class="discover-note">Same title, artist and release date. Different editions may have different content; choose the one you want to save. These records have not been merged.</p><div class="edition-options">${m.version_options.map(r=>`<button class="secondary" data-edition="${esc(r.id)}">${esc(sourceNames(r))}${r.facts?.Edition?' · '+esc(r.facts.Edition):''} · View edition</button>`).join('')}</div></section>`:'';}
function liveActionsMarkup(m){const entry=owned(fromMetadata(m));return entry?`<span class="library-membership">✓ In your library</span><div class="media-action-row"><button class="favorite-control" aria-pressed="${!!entry.favorite}" id="live-favorite"><span aria-hidden="true">♥</span> ${entry.favorite?'Favorited':'Favorite'}</button><button class="secondary" id="live-open-library">View library entry</button><button class="remove" id="live-remove">Remove from library</button></div>`:'<button class="primary" id="live-detail-add">＋ Add to library</button>';}
function bindLiveActions(m){const entry=owned(fromMetadata(m));if(!entry){liveDialog.querySelector('#live-detail-add').onclick=e=>importLive(m,e.currentTarget);return;}liveDialog.querySelector('#live-favorite').onclick=e=>{toggleLibraryFavorite(entry,e.currentTarget);};liveDialog.querySelector('#live-remove').onclick=()=>removeLibraryEntry(entry);liveDialog.querySelector('#live-open-library').onclick=()=>{liveDialog.close();openOwnedDetail(entry.id);};}
async function showLive(m){const seq=++detailSeq;liveDialog.innerHTML='<button class="close" aria-label="Close provider details">×</button><p role="status">Loading full details…</p>';liveDialog.querySelector('.close').onclick=()=>liveDialog.close();if(!liveDialog.open)liveDialog.showModal();try{const detail=await getDetail(m);if(seq!==detailSeq||!liveDialog.open)return;liveDialog.innerHTML=detailMarkup(detail);liveDialog.querySelector('.close').onclick=()=>liveDialog.close();bindLiveActions(detail);liveDialog.querySelectorAll('[data-edition]').forEach(button=>button.onclick=()=>{const selected=m.version_options.find(r=>r.id===button.dataset.edition);const {version_options,...current}=m;showLive({...selected,version_options:[current,...(version_options||[]).filter(r=>r.id!==selected.id)]});});liveDialog.querySelectorAll('img').forEach(img=>img.onerror=()=>{img.hidden=true;});const i=liveRecords.findIndex(x=>x.id===m.id);if(i>=0){const members=FolioIdentity.records(detail).map(({version_options,...r})=>r);const ids=new Set(members.map(r=>r.id));liveRecords=liveRecords.filter(r=>!ids.has(r.id)).concat(members);}facets();drawResults();}catch(e){if(seq===detailSeq&&liveDialog.open){const p=liveDialog.querySelector('p');p.textContent=e.message;}}}
liveEl('live-form').onsubmit=e=>{e.preventDefault();if(liveEl('live-query').value.trim())loadResults();};for(const id of ['live-kind','live-provider'])liveEl(id).onchange=()=>{if(liveEl('live-query').value.trim())loadResults();};for(const id of ['live-year','live-genre','live-platform','live-owned','live-sort'])liveEl(id).onchange=drawResults;liveEl('live-reset').onclick=()=>{for(const id of ['live-kind','live-provider','live-year','live-genre','live-platform','live-owned'])liveEl(id).value='';liveEl('live-sort').value='relevance';if(liveQuery)loadResults();else drawResults();};liveEl('live-more').onclick=()=>loadResults(true);drawResults();

// Close only genuine backdrop clicks, including the original library status dialog.
for(const dialog of document.querySelectorAll('dialog')){
  let beganOutside=false;
  const outside=e=>{const r=dialog.getBoundingClientRect();return e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom);};
  dialog.addEventListener('pointerdown',e=>{beganOutside=outside(e);});
  dialog.addEventListener('click',e=>{if(beganOutside&&outside(e))dialog.close();beganOutside=false;});
}
liveEl('live-query').addEventListener('input',e=>{
  clearTimeout(liveTimer);searchController?.abort();++liveSeq;liveLoading=false;
  liveRecords=[];liveMore=false;liveQuery=e.target.value.trim();liveEl('live-results').setAttribute('aria-busy','false');facets();drawResults();
  liveEl('live-providers').textContent='';
  liveEl('live-status').textContent=liveQuery.length<2?'Type at least 2 characters to search.':'Waiting for you to finish typing…';
  if(liveQuery.length>=2)liveTimer=setTimeout(()=>loadResults(),600);
});

// Keep the document fixed while any modal is open; preserve its exact scroll position.
let modalScroll=null,priorBodyStyle=null,priorRootOverflow='';
function syncModalScroll(){const open=!!document.querySelector('dialog[open]');if(open&&modalScroll===null){modalScroll=window.scrollY;priorBodyStyle={position:document.body.style.position,top:document.body.style.top,width:document.body.style.width,overflow:document.body.style.overflow};priorRootOverflow=document.documentElement.style.overflow;Object.assign(document.body.style,{position:'fixed',top:`-${modalScroll}px`,width:'100%',overflow:'hidden'});document.documentElement.style.overflow='hidden';}else if(!open&&modalScroll!==null){const y=modalScroll;Object.assign(document.body.style,priorBodyStyle);document.documentElement.style.overflow=priorRootOverflow;modalScroll=null;window.scrollTo({top:y,behavior:'instant'});}}
new MutationObserver(syncModalScroll).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});

function paintLibrarySources(){document.querySelectorAll('[data-library-id]').forEach(card=>{const entry=items.find(x=>x.id===card.dataset.libraryId);if(!entry?.metadata)return;const info=card.querySelector('.card-info');if(!info||info.querySelector('.library-source'))return;const label=document.createElement('span');label.className='library-source';label.textContent=sourceNames(entry.metadata);label.title='Metadata from '+sourceNames(entry.metadata);info.append(label);});}
function provenanceMarkup(m){return `<details class="library-provenance"><summary>Metadata · ${esc(sourceNames(m))}</summary><div>${FolioIdentity.records(m).map(r=>`<a href="${esc(safeMediaUrl(r.source.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(sourceNames(r))} ↗</a>`).join('')}</div></details>`;}
function toggleLibraryFavorite(entry,button){const prior=entry.favorite;entry.favorite=!prior;if(!persist()){entry.favorite=prior;return;}button.setAttribute('aria-pressed',String(entry.favorite));button.innerHTML='<span aria-hidden="true">♥</span> '+(entry.favorite?'Favorited':'Favorite');button.classList.remove('favorite-burst');void button.offsetWidth;if(entry.favorite)button.classList.add('favorite-burst');render();drawResults();}
function removeLibraryEntry(entry){
 const index=items.findIndex(x=>x.id===entry.id);if(index<0)return;
 const before=collections.map(c=>({...c,members:[...c.members]}));
 items.splice(index,1);collections.forEach(c=>{c.members=c.members.filter(id=>id!==entry.id);});
 if(!persist()||!saveCollections()){items.splice(index,0,entry);collections=before;persist();saveCollections();return;}
 for(const id of ['detail','live-detail','live-add-dialog'])if(liveEl(id)?.open)liveEl(id).close();render();drawResults();
 document.querySelector('.library-undo')?.remove();const notice=document.createElement('div');notice.className='library-undo';notice.setAttribute('role','status');notice.append(document.createTextNode('Removed '+entry.title+' '));const undo=document.createElement('button');undo.textContent='Undo';notice.append(undo);document.body.append(notice);
 undo.onclick=()=>{if(items.some(x=>x.id===entry.id)){notice.remove();return;}items.splice(Math.min(index,items.length),0,entry);const current=collections.map(c=>({...c,members:[...c.members]}));collections.forEach(c=>{if(before.find(old=>old.id===c.id)?.members.includes(entry.id))c.members=[...new Set([...c.members,entry.id])];});if(!persist()||!saveCollections()){items=items.filter(x=>x.id!==entry.id);collections=current;persist();saveCollections();return;}notice.remove();render();drawResults();toast('Restored to your library');};setTimeout(()=>notice.remove(),10000);
}
const originalOwnedPopup=openOwnedDetail;
openOwnedDetail=function(id){originalOwnedPopup(id);const entry=items.find(x=>x.id===id);if(!entry)return;const summary=liveEl('detail-content').querySelector('.popup-summary');if(!summary)return;summary.insertAdjacentHTML('afterend',`<div class="media-action-row owned-actions"><button class="favorite-control" id="owned-favorite" aria-pressed="${!!entry.favorite}"><span aria-hidden="true">♥</span> ${entry.favorite?'Favorited':'Favorite'}</button><button class="remove" id="owned-remove">Remove from library</button></div>${entry.metadata?provenanceMarkup(entry.metadata):''}`);liveEl('owned-favorite').onclick=e=>toggleLibraryFavorite(entry,e.currentTarget);liveEl('owned-remove').onclick=()=>removeLibraryEntry(entry);};
